});

test('createInvoice returns copies of product data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  result.value.lines[0].unitPrice = 1;
